function applyTheme() {
  const theme = state.get('settings.theme') || 'dark';
  document.documentElement.setAttribute('data-theme', theme);
}

function isFullscreen() {
  return !!document.fullscreenElement;
}

function toggleFullscreen() {
  if (isFullscreen()) {
    document.exitFullscreen().catch(() => {});
  } else {
    document.documentElement.requestFullscreen().catch(() => {});
  }
}

function updateFullscreenBtn(btn) {
  if (!btn) return;
  btn.textContent = isFullscreen() ? '關閉全螢幕' : '開啟全螢幕';
}

function closeAllModals(){
  document.querySelectorAll('dialog[open]').forEach(d=>{
    try{ d.close(); }catch{}
  });
  // non-dialog overlays that also block clicks
  const startMenu = document.getElementById('startMenu');
  if(startMenu) startMenu.style.display='none';
  const intraPreview = document.getElementById('intraPreview');
  if(intraPreview) intraPreview.style.display='none';
  const darkPreview = document.getElementById('darkPreview');
  if(darkPreview) darkPreview.style.display='none';
  const waLightbox = document.getElementById('waLightbox');
  if(waLightbox) waLightbox.classList.remove('open');
  // clean leftover inline display from legacy fallback
  document.querySelectorAll('dialog').forEach(d=>{
    if(!d.open){
      d.style.removeProperty('display');
    }
  });
}

function switchView(id) {
  // Close any modal first — prevents backdrop from blocking the newly activated view
  closeAllModals();
  // All interfaces are unlocked from the start — free navigation
  setActiveView(id);
  localStorage.setItem('cc_active_view', id);
}

function mountAll() {
  mountVSCode();
  mountJira();
  mountWhatsApp();
  mountSearch();
  mountIntranet();
  mountDarknet();
  bindMail();
  bindStartMenu();
  bindEnding();
}

// Windows-style WhatUp notification (bottom-right, 10s, click -> Dev Team chat) - only once per game at chp0
let _notifTimer = null;
function isChatMutedForNotify(id){
  try{
    const raw = JSON.parse(localStorage.getItem('code_conspiracy_state')||'{}');
    const chats = raw.whatsappChats;
    if(Array.isArray(chats)){
      const c = chats.find(x=>x.id===id);
      if(c) return !!c.muted;
    }
    // fallback to in-memory if not yet persisted
    return false;
  }catch{ return false; }
}
function showMaggieNotification() {
  // Only show once per game at chp0 (and again after reset to chp0) — persisted via localStorage
  // Check both in-memory flags and raw storage to survive debounced-save edge cases
  try {
    const raw = JSON.parse(localStorage.getItem('code_conspiracy_state') || '{}');
    if (raw.flags && raw.flags.ch0_maggie_notified) return;
    if (raw.flags && raw.flags.ch0_vip_fixed) return;
    if (raw.currentChapter && raw.currentChapter !== 0) return;
  } catch {}
  if (state.hasFlag('ch0_maggie_notified')) return;
  if (state.hasFlag('ch0_vip_fixed')) return;
  if ((state.get('currentChapter') ?? 0) !== 0) return;
  if (isChatMutedForNotify('maggie')) return;
  // avoid duplicate if already shown this session
  if (document.getElementById('wa-win-notification')) return;

  const container = document.createElement('div');
  container.id = 'wa-win-notification';
  container.setAttribute('role', 'alert');
  container.setAttribute('aria-live', 'polite');
  container.innerHTML = `
    <div class="win-notif__app">
      <img src="${import.meta.env.BASE_URL}icon/whatsup.svg" alt="WhatUp" width="20" height="20" style="width:20px;height:20px;object-fit:contain" />
      <span class="win-notif__app-name">WhatUp</span>
      <span class="win-notif__app-sub">主管 - Maggie</span>
      <button class="win-notif__close" aria-label="關閉">✕</button>
    </div>
    <div class="win-notif__body">
      <div class="win-notif__avatar">M</div>
      <div class="win-notif__text">
        <div class="win-notif__sender">Maggie</div>
        <div class="win-notif__msg">Hi @Casey, 有新的工單 INV-2024-0042, 請協助處理一下</div>
        <div class="win-notif__time">剛剛 · 點擊開啟對話</div>
      </div>
    </div>
    <div class="win-notif__progress"></div>
  `;

  // click anywhere on notification -> open WhatUp Dev Team
  container.addEventListener('click', (e) => {
    // close button handled separately
    if (e.target.closest('.win-notif__close')) return;
    dismissNotification();
    // Ensure WhatUp is mounted then switch
    try { openWhatsAppChat('maggie'); } catch (_) {}
    switchView('whatsapp');
  });

  container.querySelector('.win-notif__close')?.addEventListener('click', (e) => {
    e.stopPropagation();
    dismissNotification();
  });

  document.body.appendChild(container);
  // Mark as notified so it only shows once per game at chp0 (until reset)
  state.setFlag('ch0_maggie_notified', true);
  // trigger entrance
  requestAnimationFrame(() => container.classList.add('show'));

  // auto dismiss after 10s
  _notifTimer = setTimeout(() => dismissNotification(), 10000);
  // also emit toast for accessibility but keep win style primary
}

function dismissNotification() {
  const el = document.getElementById('wa-win-notification');
  if (!el) return;
  clearTimeout(_notifTimer);
  el.classList.remove('show');
  el.classList.add('hide');
  setTimeout(() => el.remove(), 280);
}

// Keep for backwards compat — Jiua still calls trackOnboarding
export function trackOnboarding(action) {
  if (action === 'jira_viewed') state.setFlag('onb_jira_viewed', true);
  if (action === 'vscode_viewed') state.setFlag('onb_vscode_viewed', true);
  // Auto-complete onboarding flag since dialog is removed; no gating
  if (!state.hasFlag('onboarding_done')) state.setFlag('onboarding_done', true);
}

function bindMail() {
  const dialog = document.getElementById('mailDialog');
  const title = document.getElementById('mailTitle');
  const to = document.getElementById('mailTo');
  const send = document.getElementById('mailSend');
  const tempExit = document.getElementById('mailTempExit');
  function updateTo() {
    if (!title || !to) return;
    const v = title.value;
    if (v === 'Report') to.value = 'Drug Enforcement Administration <dea@email.us>';
    else if (v === 'Coperation') to.value = 'Sawyer <sawyer@nori.com>';
    else if (v === 'Resign') to.value = 'Sawyer <sawyer@nori.com>';
  }
  title?.addEventListener('change', updateTo);
  updateTo();
  tempExit?.addEventListener('click', () => {
    dialog?.close();
    // keep email app visible for later
    renderDock({ onSwitch: switchView, onOpenSettings: openSettings, onOpenNotebook: openNotebook, t });
  });
  send?.addEventListener('click', () => {
    const v = title?.value;
    const body = document.getElementById('mailBody')?.value || '';
    const toVal = document.getElementById('mailTo')?.value || '';
    // 數據追蹤：Email 提交（完整去識別後寫入 Sheets）
    try{ trackEmailSubmit({ title: v, to: toVal, body }); }catch{}
    let ending = null;
    if (v === 'Report') ending = 'report';
    else if (v === 'Coperation') ending = 'cooperate';
    else if (v === 'Resign') ending = 'resign';
    if (ending) {
      const endings = state.get('endings') || [];
      if (!endings.includes(ending)) {
        endings.push(ending);
        state.set('endings', endings);
        state.setFlag('ending_' + ending, true);
      }
      try{ trackEnding(ending); }catch{}
    } else {
      try{ analyticsTrack('email_submit_no_ending', { email_title: v, email_body_preview: body.slice(0,80) }); }catch{}
    }
    dialog?.close();
    renderDock({ onSwitch: switchView, onOpenSettings: openSettings, onOpenNotebook: openNotebook, t });
    if (ending) {
      // Show black screen ending with typing effect as per spec
      setTimeout(() => showEnding(ending), 300);
    } else {
      toast('郵件已寄送: ' + v);
    }
  });
  // Also handle dialog close via backdrop
}

function bindStartMenu() {
  const menu = document.getElementById('startMenu');
  if (!menu) return;
  // Use delegated handler so re-render of #dock (which recreates .taskbar__start) does not lose the listener
  document.addEventListener('click', (e) => {
    const startBtn = e.target.closest && e.target.closest('.taskbar__start');
    const shutdownBtn = e.target.closest && e.target.closest('#startShutdown');
    const logoutBtn = e.target.closest && e.target.closest('#startLogout');
    if (startBtn) {
      e.stopPropagation();
      const isHidden = menu.style.display === 'none' || !menu.style.display || menu.style.display === '';
      menu.style.display = isHidden ? 'block' : 'none';
      return;
    }
    if (shutdownBtn) {
      e.stopPropagation();
      menu.style.display = 'none';
      handleShutdown('shutdown');
      return;
    }
    if (logoutBtn) {
      e.stopPropagation();
      menu.style.display = 'none';
      handleShutdown('logout');
      return;
    }
    if (!menu.contains(e.target)) {
      menu.style.display = 'none';
    }
  });
}

function handleShutdown(action) {
  const endings = state.get('endings') || [];
  const hasAllDark = state.hasFlag('ch4_all_opened');
  const choice = endings[0];
  let ending = null;
  if (!choice && !hasAllDark) ending = 'flee'; // Ending1 - any logout without mail and without all dark files
  else if (!choice && hasAllDark) ending = 'fried'; // Ending5 - ch5 after logout with all files but no mail choice
  else if (choice === 'report') ending = 'report'; // Ending3
  else if (choice === 'cooperate') ending = 'cooperate'; // Ending2
  else if (choice === 'resign') ending = 'resign'; // Ending4
  else ending = 'flee';
  // push to endings if not already
  const allEndings = state.get('endings') || [];
  if (!allEndings.includes(ending)) {
    allEndings.push(ending);
    state.set('endings', allEndings);
  }
  try{ trackEnding(ending); analyticsTrack('shutdown', { action, ending }); }catch{}
  showEnding(ending);
}

function showEnding(ending) {
  const screen = document.getElementById('endingScreen');
  const title = document.getElementById('endingTitle');
  const desc = document.getElementById('endingDesc');
  const restartBtn = document.getElementById('endingRestart');
  if (!screen || !title || !desc) return;

  // Play ending BGM
  const endingBgmMap = {
    flee: 'flee',
    cooperate: 'cooperate',
    report: 'report',
    resign: 'resign',
    fried: 'fried'
  };
  const bgmKey = endingBgmMap[ending];
  if (bgmKey) bgm.play(bgmKey);

  const map = {
    flee: { title: '平凡的日常', desc: 
      '你已完成了工作，登出了電腦，走出辨公室，回到家中安心睡一覺。\n第二天回到辨公室，重新開啟電腦，像平常一樣進入辨公模式，但你感覺有點不對勁，昨天看到的一些文件不見了，有部分git history好像有被人改動過的痕跡，你認為你記錯了。\n接下來繼續日復日的重複性工作，漸漸對此工作感到沉悶，但也只能接受不變的人生。' },
    cooperate: { title: '共犯', desc: '你認為老闆是對的。\n你向老闆自告奮勇，參與運毒的工作。不到一日，已分潤到可觀的額外收入，你的生活質素大幅上升，不用再為了是否升級麥當當套餐而煩惱，但可能要為隨時被人闖入家中爆頭感到恐懼。\n你踏出新的這一步，為生活帶來了多一分選擇，不再是一成不變的勞動人生，你更喜歡這充滿刺激的生活。' },
    report: { title: '舉報', desc: '你認為老闆是不對的。\n你選擇向輯毒處舉報，你把證據從內網下載下來，郵寄至警方。\n不一會兒，警方到達辨公室，帶住拘捕令走進老闆辨公室，你看着本來充滿笑容的老闆變得呆滯，在眾多員工的眼前被警方押走。\n這件事被傳媒大幅報導，公司也跟著倒閉，市面上出產過的飲品通通下架。\n風波後過了幾個禮拜，人們都忘記了，不再是閒餘茶飯時會提及的話題，你也回到了正常生活，找了一份新的工作，又回到日復日的勞動中。' },
    resign: { title: '辭職', desc: '你發現了公司的秘密。\n你知道對於社會倫理和規範來說是不對的，但你選擇遠離，不參與事端，你希望少一事是一事，因此向老闆提出離職，以不適合這份工作為理由矇混過去。\n老闆了解這年代的年輕人都很有主見，必定是深思熟慮過後的決定，因此沒強留着你，只是拉着你聊了一會兒。\n你對這愉快的工作環境感到不捨，過了幾個月，你找到了新工作，開始淡忘這兩個月的記憶，也不再在意。' },
    fried: { title: '做對了嗎？', desc: '你發現了公司的秘密。\n但你沒有做出任何行動，你默默的關掉電腦，下班回到家裡，打算好好的休息明天再回到辨公室繼續上班。\n突然，放在櫃子上的手機震動了一下，收到了公司辭退你的消息。\n其實\n公司也發現了你。' },
  };

  const info = map[ending] || map.flee;

  // Show dialog + title immediately, content will appear after 500ms with typing
  title.textContent = info.title;
  desc.textContent = '';
  if (restartBtn) restartBtn.style.display = 'none';

  // Ensure desc preserves line breaks
  desc.style.whiteSpace = 'pre-wrap';
  desc.style.wordBreak = 'break-word';

  setTimeout(() => {
    screen.style.display = 'flex';
    screen.style.background = '#000';

    // Typing effect - 1 sec per word, +200ms extra at ，/。/、/！/？/； and at \n
    // Split text into words keeping delimiters, chunk Chinese into 4-char words
    let words = [];
    const text = info.desc.replace(/br/g, '\n').replace(/\n+/g, '\n');
    // Normalize: ensure \n are preserved as separate tokens
    const parts = text.split(/([，。、！？；\n\s]+)/).filter(Boolean);
    for (const p of parts) {
      if (/^[\n\s]+$/.test(p)) {
        words.push(p);
      } else if (/^[，。、！？；]+$/.test(p)) {
        words.push(p);
      } else {
        // Chunk long Chinese/English segments into ~4 char words for 1s per word rhythm
        for (let i = 0; i < p.length; i += 1) {
          words.push(p.slice(i, i + 1));
        }
      }
    }

    let wIdx = 0;
    let displayed = '';
    function typeNextWord() {
      if (wIdx >= words.length) {
        if (restartBtn) restartBtn.style.display = 'block';
        return;
      }
      const w = words[wIdx];
      displayed += w;
      // Use textContent with pre-wrap to correctly show \n as line breaks; fallback to innerHTML if needed
      desc.textContent = displayed;
      wIdx++;
      // Determine delay: base 1000ms per word, +200ms if word ends with ，/。/、/！/？/； or is \n
      let delay = 100;
      if (/[，。、！？；]$/.test(w) || w === '\n' || w.includes('\n')) {
        delay += 200;
      }
      // If word is just whitespace/newline, don't add extra 1000, just 200
      if (/^\s+$/.test(w)) delay = 100;
      // fried ending: slow down final two lines for dramatic effect
      if (ending === 'fried' && (w === '其' || w === '實' || displayed.includes('其實'))) {
        delay = 420;
      }
      setTimeout(typeNextWord, delay);
    }
    typeNextWord();
  }, 500);
}

function bindEnding() {
  document.getElementById('endingRestart')?.addEventListener('click', async () => {
    bgm.stop(false);
    // Preserve achievement / persistentStats across replay — do NOT wipe localStorage after reset
    // state.reset() already merges current endings into persistentStats.unlockedEndings and saves
    let savedPersistent = null;
    try { savedPersistent = JSON.parse(JSON.stringify(state.get('persistentStats') || {})); } catch {}
    try { state.reset(); } catch {}
    // state.reset() already saved persistentStats; ensure it is not cleared by stale remove/clear calls
    // re-assert persistentStats in case any legacy clear logic runs (keep for safety)
    try {
      if (savedPersistent) {
        const cur = state.get('persistentStats') || {};
        // merge saved into current (in case reset was called before we captured)
        const merged = {
          unlockedEndings: [...new Set([...(cur.unlockedEndings||[]), ...(savedPersistent.unlockedEndings||[])])],
          readArticles: [...new Set([...(cur.readArticles||[]), ...(savedPersistent.readArticles||[])])],
          darkFileCount: Math.max(cur.darkFileCount||0, savedPersistent.darkFileCount||0),
          whatsappSentCount: Math.max(cur.whatsappSentCount||0, savedPersistent.whatsappSentCount||0),
          searchHistoryCount: Math.max(cur.searchHistoryCount||0, savedPersistent.searchHistoryCount||0),
          flags: { ...(cur.flags||{}), ...(savedPersistent.flags||{}) }
        };
        state.set('persistentStats', merged);
        // legacy mirror for old notebook reads
        state.set('unlockedEndings', merged.unlockedEndings);
      }
    } catch {}
    // Do NOT clear code_conspiracy_state — it now contains persistentStats. Only clear unrelated keys if needed.
    // Remove the previous destructive clears that wiped achievements.
    const screen = document.getElementById('endingScreen');
    if (screen) screen.style.display = 'none';
    // Close any open dialogs
    document.querySelectorAll('dialog[open]').forEach(d => { try { d.close(); } catch {} d.style.display = 'none'; });
    try {
      if ('caches' in window) {
        const keys = await caches.keys();
        await Promise.all(keys.map(k => caches.delete(k)));
      }
      if ('serviceWorker' in navigator) {
        const regs = await navigator.serviceWorker.getRegistrations();
        await Promise.all(regs.map(r => r.unregister()));
      }
    } catch {}
    setTimeout(() => {
      window.location.href = window.location.pathname + '?reset=' + Date.now();
      window.location.reload(true);
    }, 150);
  });
  document.getElementById('endingClose')?.addEventListener('click', () => {
    document.getElementById('endingScreen').style.display = 'none';
  });
}

function showWelcomeDialog() {
  const dlg = document.getElementById('welcomeDialog');
  if (!dlg) return;
  const fsBtn = document.getElementById('welcomeFullscreenBtn');
  const muteBtn = document.getElementById('welcomeMuteBtn');
  const slider = document.getElementById('welcomeVolumeSlider');
  const pctEl = document.getElementById('welcomeVolumePct');
  const startBtn = document.getElementById('welcomeStartBtn');

  updateFullscreenBtn(fsBtn);

  fsBtn?.addEventListener('click', () => {
    toggleFullscreen();
    updateFullscreenBtn(fsBtn);
  });

  document.addEventListener('fullscreenchange', () => {
    updateFullscreenBtn(fsBtn);
    // Also update settings fullscreen button if visible
    const sFsBtn = document.getElementById('settingFullscreenBtn');
    updateFullscreenBtn(sFsBtn);
  });

  if (muteBtn) {
    muteBtn.addEventListener('click', () => {
      const muted = bgm.toggleMute();
      muteBtn.textContent = muted ? '🔇' : '🔊';
      if (pctEl) pctEl.textContent = muted ? '靜音' : Math.round(bgm.getVolume() * 100) + '%';
    });
  }
  if (slider) {
    slider.addEventListener('input', (e) => {
      const v = parseInt(e.target.value) / 100;
      bgm.setVolume(v);
      bgm.setMuted(false);
      if (muteBtn) muteBtn.textContent = '🔊';
      if (pctEl) pctEl.textContent = Math.round(v * 100) + '%';
    });
  }

  startBtn?.addEventListener('click', () => {
    dlg.close();
  });

  if (typeof dlg.showModal === 'function') {
    dlg.showModal();
  } else {
    dlg.show();
  }
}

function bindSettingsFullscreen() {
  const btn = document.getElementById('settingFullscreenBtn');
  if (!btn) return;
  updateFullscreenBtn(btn);
  btn.addEventListener('click', () => {
    toggleFullscreen();
    updateFullscreenBtn(btn);
  });
}

function bindAnalytics(){
  const banner = document.getElementById('analyticsBanner');
  const accept = document.getElementById('analyticsAccept');
  const decline = document.getElementById('analyticsDecline');
  const toggle = document.getElementById('analyticsConsentToggle');
  const gasInput = document.getElementById('analyticsGasUrl');
  const saveBtn = document.getElementById('analyticsSaveBtn');
  const testBtn = document.getElementById('analyticsTestBtn');
  const flushBtn = document.getElementById('analyticsFlushBtn');
  const status = document.getElementById('analyticsStatus');
  const queueEl = document.getElementById('analyticsQueueCount');
  const sidEl = document.getElementById('analyticsSessionId');

  // Banner: show only if no choice yet
  try{
    if(banner && !hasConsentChoice()){
      banner.style.display = 'flex';
    }
  }catch{}

  const refreshStatus = () => {
    try{
      const q = JSON.parse(localStorage.getItem('cc_analytics_queue') || '[]');
      if(queueEl) queueEl.textContent = String(q.length);
      if(sidEl) sidEl.textContent = getSessionId().slice(0,8);
      if(status){
        if(!isGasConfigured()) status.textContent = '尚未設定 GAS URL（需部署時設定 VITE_GAS_URL，其他玩家才會自動生效）';
        else if(!getConsent()) status.textContent = '已設定，等待玩家同意';
        else status.textContent = '就緒（所有玩家自動共用此 URL，無需各自輸入）';
      }
      if(toggle) toggle.checked = getConsent();
      if(gasInput){
        // 若由建置時 VITE_GAS_URL 注入，所有玩家共用，玩家無需各自輸入
        let envHas = false;
        try{ envHas = !!import.meta.env.VITE_GAS_URL; }catch{}
        if(isGasConfigured()){
          gasInput.value = getGasUrl();
          gasInput.disabled = false;
          if(envHas){
            try{ if(!localStorage.getItem('cc_gas_url')) gasInput.title = '已由 GitHub Secrets VITE_GAS_URL 注入，所有玩家共用，無需各自輸入'; }catch{}
            gasInput.placeholder = '已由部署設定（所有玩家自動共用）';
          } else {
            gasInput.placeholder = 'https://script.google.com/macros/s/.../exec';
          }
        } else {
          gasInput.value = '';
          gasInput.disabled = false;
          gasInput.placeholder = 'https://script.google.com/macros/s/.../exec';
        }
      }
    }catch{}
  };
  refreshStatus();

  accept?.addEventListener('click', ()=>{ setConsent(true); if(banner) banner.style.display='none'; refreshStatus(); toast('已啟用匿名數據收集'); flushQueue(); });
  decline?.addEventListener('click', ()=>{ setConsent(false); if(banner) banner.style.display='none'; refreshStatus(); toast('已拒絕數據收集'); });
  toggle?.addEventListener('change', (e)=>{ setConsent(e.target.checked); refreshStatus(); toast(e.target.checked ? '已啟用' : '已停用'); });
  saveBtn?.addEventListener('click', ()=>{
    const v = gasInput?.value.trim() || '';
    if(v && !v.startsWith('https://script.google.com/')){ if(status) status.textContent='URL 需為 https://script.google.com/.../exec'; return; }
    setGasUrl(v);
    refreshStatus();
    toast('已儲存 GAS URL');
  });
  testBtn?.addEventListener('click', async ()=>{
    if(!isGasConfigured()){ toast('請先設定 GAS URL'); if(status) status.textContent='未設定：請貼上你部署的 exec URL'; return; }
    if(!getConsent()){ toast('請先勾選 同意匿名收集'); if(status) status.textContent='等待同意：請先勾選同意'; return; }
    if(status) status.textContent = '發送中...';
    const url = getGasUrl();
    const payload = { timestamp: new Date().toISOString(), session_id: getSessionId(), event_type: 'test_ping', chapter: 0, payload_json: JSON.stringify({test:true, from:'settings_test_btn'}) };
    try{
      const res = await fetch(url, { method:'POST', headers:{'Content-Type':'text/plain;charset=utf-8'}, body: JSON.stringify(payload), redirect:'follow', mode:'cors' });
      const text = await res.text();
      let data = null; try{ data = JSON.parse(text); }catch{}
      if(data && data.ok){
        toast('測試成功！Sheets 已新增一列');
        if(status) status.textContent = '成功：Sheets 已寫入 test_ping';
      } else {
        toast('GAS 回應異常：' + text.slice(0,120));
        if(status) status.textContent = 'GAS 回應：' + (data?.error || text.slice(0,80));
        console.warn('[analytics] test response', text);
      }
    }catch(err){
      console.warn('[analytics] test fetch 失敗', err);
      // fallback 仍走 analyticsTrack 入隊，稍後 flush
      analyticsTrack('test_ping', { payload_json: JSON.stringify({test:true, fallback:true}) });
      if(status) status.textContent = '網路錯誤，已入隊（查看 Console）';
      toast('網路錯誤，已入隊重試');
    }
    refreshStatus();
  });
  flushBtn?.addEventListener('click', ()=>{ flushQueue(); refreshStatus(); toast('已嘗試補送，查看 Console 與 Sheets'); setTimeout(refreshStatus, 800); });

  // Keep queue count live
  setInterval(refreshStatus, 2000);
  // Expose for debug
  try{ window.__analyticsRefresh = refreshStatus; }catch{}
}

function init() {
  applyTheme();
  renderDock({ onSwitch: switchView, onOpenSettings: openSettings, onOpenNotebook: openNotebook, t });
  bindSettings();
  bindSettingsFullscreen();
  try{ initAnalytics(); }catch{}
  bindAnalytics();
  mountAll();
  const last = localStorage.getItem('cc_active_view') || 'vscode';
  switchView(state.get('unlockedInterfaces').includes(last) ? last : 'vscode');
  startEngine();
  // Start default BGM
  bgm.play('default');
  // Mark onboarding done immediately (no dialog) so engine progresses
  if (!state.hasFlag('onboarding_done')) state.setFlag('onboarding_done', true);
  // Show welcome dialog on first open (never again after reset/refresh)
  if (!state.hasFlag('welcome_dialog_shown')) {
    state.setFlag('welcome_dialog_shown', true);
    setTimeout(() => showWelcomeDialog(), 400);
  }
  // Show Windows-style WhatUp notification shortly after load
  setTimeout(() => showMaggieNotification(), 800);
  events.on('puzzle:solved', p => { toast('✓ ' + p.title); try{ analyticsTrack('puzzle_solved', { puzzle: p.id, chapter: p.chapter }); }catch{} });
  events.on('interfaceUnlocked', id => { toast(t('toast.unlocked') + ': ' + id); renderDock({ onSwitch: switchView, onOpenSettings: openSettings, onOpenNotebook: openNotebook, t   }); try{ analyticsTrack('interface_unlocked', { iface: id }); }catch{}
});
  events.on('evidence', e => { toast(t('toast.evidence') + ': ' + e.title); try{ analyticsTrack('evidence_collected', { evidence: e.id }); }catch{} });
  state.on('change', () => applyTheme());
  // Auto-popup email after ch4 (darknet all files opened and exited)
  window.addEventListener('ch4:complete', () => {
    state.setFlag('ch5_triggered', true);
    renderDock({ onSwitch: switchView, onOpenSettings: openSettings, onOpenNotebook: openNotebook, t });
    setTimeout(() => {
      const dlg = document.getElementById('mailDialog');
      if (dlg && !dlg.open) {
        // Update To field
        const title = document.getElementById('mailTitle');
        const to = document.getElementById('mailTo');
        if (title && to) {
          const v = title.value;
          if (v === 'Report') to.value = 'DEA <dea@world.example>';
          else if (v === 'Coperation') to.value = 'Sawyer <sawyer@nori-drinks.example>';
          else if (v === 'Resign') to.value = 'Sawyer <sawyer@nori-drinks.example>';
        }
        dlg.showModal();
      }
    }, 600);
  });
  window.addEventListener('darknet:exit', () => {
    // Switch back to default BGM when leaving darknet
    bgm.play('default');
    if (state.hasFlag('ch4_all_opened') && !state.hasFlag('ch5_triggered')) {
      state.setFlag('ch5_triggered', true);
      renderDock({ onSwitch: switchView, onOpenSettings: openSettings, onOpenNotebook: openNotebook, t });
      setTimeout(() => {
        const dlg = document.getElementById('mailDialog');
        if (dlg && !dlg.open) dlg.showModal();
      }, 400);
    } else if (state.hasFlag('ch5_triggered')) {
      // Ensure email app is visible and also auto-popup if not yet sent
      const endings = state.get('endings') || [];
      if (!endings.length) {
        setTimeout(() => {
          const dlg = document.getElementById('mailDialog');
          if (dlg && !dlg.open) dlg.showModal();
        }, 400);
      }
    }
  });
  // Also listen for state flag change for ch5_triggered to re-render dock
  state.on('change', (e) => {
    if (e && e.path && e.path.includes('ch5_triggered')) {
      renderDock({ onSwitch: switchView, onOpenSettings: openSettings, onOpenNotebook: openNotebook, t });
    }
    // Darknet entry BGM: switch to darknet music when dark_entered flag is set
    if (e && e.path && e.path.includes('dark_entered')) {
      bgm.play('darknet');
    }
    // Ch1 Event1 trigger: 10s after ch0 (VIP fix) done, Sawyer tree message
    if (e && e.path && e.path.includes('ch0_vip_fixed') && !state.hasFlag('ch1_event1_triggered')) {
      state.setFlag('ch1_event1_triggered', true);
      setTimeout(() => {
        import('./apps/whatsapp/index.js').then(m => {
          if (m.triggerCh1Event1) m.triggerCh1Event1();
        });
      }, 10000);
    }
    // Ch2 init: 午餐小隊爆炸對話 — when currentChapter becomes 2 (after revert)
    if (e && e.path === 'currentChapter' && e.value === 2 && !state.hasFlag('ch2_lunch_seq_done')) {
      setTimeout(() => {
        import('./apps/whatsapp/index.js').then(m => {
          if (m.triggerCh2LunchSequence) m.triggerCh2LunchSequence();
        });
      }, 600);
    }
    // 數據追蹤：章節 / 暗網入口
    if (e && e.path === 'currentChapter') {
      try{ trackChapter(e.value); analyticsTrack('chapter_progress', { chapter: e.value }); }catch{}
    }
    if (e && e.path && e.path.includes('ch4_all_opened') && e.value) {
      try{ analyticsTrack('ch4_all_opened', { chapter: 4 }); }catch{}
    }
  });
  // Also check on load if ch0 already done but Event1 not yet triggered (for reload case)
  if (state.hasFlag('ch0_vip_fixed') && !state.hasFlag('ch1_event1_triggered')) {
    state.setFlag('ch1_event1_triggered', true);
    setTimeout(() => {
      import('./apps/whatsapp/index.js').then(m => {
        if (m.triggerCh1Event1) m.triggerCh1Event1();
      });
    }, 10000);
  }
  // Also check on load if already ch2 but lunch sequence not yet done (reload case)
  if (state.get('currentChapter') === 2 && !state.hasFlag('ch2_lunch_seq_done')) {
    setTimeout(() => {
      import('./apps/whatsapp/index.js').then(m => {
        if (m.triggerCh2LunchSequence) m.triggerCh2LunchSequence();
      });
    }, 900);
  }
  // Also listen for chapter:changed event (engine) for ch2 — redundant safety
  events.on('chapter:changed', (ch) => {
    if (ch === 2 && !state.hasFlag('ch2_lunch_seq_done')) {
      setTimeout(() => {
        import('./apps/whatsapp/index.js').then(m => {
          if (m.triggerCh2LunchSequence) m.triggerCh2LunchSequence();
        });
      }, 600);
    }
  });
  // Listen for Jira ticket added to re-render board
  window.addEventListener('jira:ticketAdded', () => {
    // Force re-render Jira board if visible
    const board = document.getElementById('jiraBoard');
    if (board) {
      import('./apps/jira/index.js').then(m => {
        // The tickets array is updated, we need to re-render
        // Since renderBoard is not exported, we can trigger a custom event or just reload the view
        // For now, dispatch a state change to trigger re-render
        events.emit('jira:refresh');
      });
    }
  });
  window.addEventListener('jira:refresh', () => {
    // Try to re-mount Jira if needed
    try { mountJira(); } catch {}
  });
  document.querySelectorAll('dialog').forEach(d => {
    d.addEventListener('click', e => { if (e.target === d) d.close(); });
    d.addEventListener('cancel', e => { e.preventDefault(); d.close(); });
    d.addEventListener('close', () => {
      // Native dialog hides via [open]; just clean any inline style left from legacy fallback
      d.style.removeProperty('display');
    });
  });
}

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
else init();
